+                request.getTaskIds().size(), request.getWorkspaceId());
+        if (request.getTaskIds().size() > 500) {
+            throw new BadRequestException("Bulk update limited to 500 tasks per request");
+        }
+        final var result = taskService.bulkUpdateTasks(request);
